WITH valid AS (SELECT *, REGEXP_REPLACE(store_name, ' ', '_') AS store_name_slug, COALESCE(region, 'N/A') AS region_clean FROM stores WHERE sqft >= 11864), not_flagged AS (SELECT s.* FROM valid s WHERE NOT EXISTS (SELECT 1 FROM inventory c WHERE c.store_id = s.id AND c.last_restock < s.opened_date)), with_windows AS (SELECT *, AVG(sqft) OVER (ORDER BY sqft ASC, id ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS sqft_avg_5_prior, ROW_NUMBER() OVER (PARTITION BY region ORDER BY opened_date ASC, id ASC) AS row_seq, ROW_NUMBER() OVER (PARTITION BY region, city ORDER BY sqft DESC, id ASC) AS event_seq, NTILE(5) OVER (PARTITION BY city ORDER BY sqft DESC, id ASC) AS sqft_bucket, ROW_NUMBER() OVER (PARTITION BY region ORDER BY opened_date ASC, id ASC) AS event_seq_2 FROM not_flagged) SELECT CASE WHEN event_seq >= 8 THEN 'HIGH' ELSE 'LOW' END AS event_seq_tier, COUNT(DISTINCT city) AS distinct_cities, COUNT(DISTINCT city) AS distinct_cities_2, SUM(CASE WHEN city = 'Bangkok' THEN sqft ELSE 0 END) AS bangkok_sqft, COUNT(DISTINCT region) AS distinct_regions, COUNT_IF(city = 'Bangkok') AS bangkok_events FROM with_windows GROUP BY event_seq_tier ORDER BY bangkok_events DESC NULLS LAST
